import com.fixmer.genesis.technology.server.firstlaunch.*;
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.security.spec.PKCS8EncodedKeySpec;
import java.util.*;

/** One durable client-only round. COMMITTED/admission are irreversible; this class never controls a world. */
public final class ControlRoom73 {
 public static final class Member {
  public final UUID id,account;public final byte[] secret;public final boolean original;public volatile String decision="PENDING",state="WAITING",inventory="none";public volatile String last="none";public volatile UUID ack=new UUID(0,0);public volatile boolean counted;
  Member(UUID id,UUID account,byte[] secret,boolean original){this.id=id;this.account=account;this.secret=secret.clone();this.original=original;}
 }
 public final Path root;public final RemoteOffer69 offer;public final UUID instance,round;private final PrivateKey key;private final PublicKey publicKey;private final Map<UUID,Member> accounts=new LinkedHashMap<>();private String phase="PREPARING";private boolean admission;private long serial;
 private ControlRoom73(Path root,RemoteOffer69 offer,UUID instance,UUID round,PrivateKey key,PublicKey pub){this.root=root;this.offer=offer;this.instance=instance;this.round=round;this.key=key;publicKey=pub;}
 public static ControlRoom73 create(Path root,Path identity,RemoteOffer69 offer,UUID instance,UUID round,Collection<UUID> cohort)throws Exception{
  if(cohort.size()>64||new HashSet<>(cohort).size()!=cohort.size())throw new IOException("CONTROL73_LIMIT");var keys=keys(identity);if(!offer.signer().equals(FirstLaunchFiles.sha(keys.publicBytes)))throw new IOException("CONTROL73_PUBLISHER");root=FirstLaunchFiles.safe(root);Files.createDirectories(root);FirstLaunchFiles.privateMode(root);if(Files.exists(root.resolve("active73")))throw new IOException("CONTROL73_ACTIVE");ControlRoom73 r=new ControlRoom73(root,offer,instance,round,keys.key,keys.pub);for(UUID id:cohort)r.member(id,true);r.persist();FirstLaunchFiles.write(root.resolve("active73"),round.toString().getBytes(java.nio.charset.StandardCharsets.US_ASCII),false);return r;
 }
 private record Keys(PrivateKey key,PublicKey pub,byte[] publicBytes){}
 private static Keys keys(Path identity)throws Exception{identity=FirstLaunchFiles.safe(identity);FirstLaunchFiles.privateMode(identity);FirstLaunchFiles.privateMode(identity.resolve("private.der"));byte[] pub=FirstLaunchFiles.read(identity.resolve("public.der"),256);PrivateKey k=KeyFactory.getInstance("Ed25519").generatePrivate(new PKCS8EncodedKeySpec(FirstLaunchFiles.read(identity.resolve("private.der"),256)));PublicKey p=RemoteOffer69.publicKey(pub);ControlWire73.verify(p,ControlWire73.sign(k,Map.of("test","73")));return new Keys(k,p,pub);}
 public static ControlRoom73 restore(Path root,Path identity)throws Exception{
  root=FirstLaunchFiles.safe(root);var keys=keys(identity);UUID round=UUID.fromString(new String(FirstLaunchFiles.read(root.resolve("active73"),64),java.nio.charset.StandardCharsets.US_ASCII));var m=ControlWire73.verify(keys.pub,FirstLaunchFiles.read(root.resolve(round+".journal"),131072));if(!m.keySet().equals(Set.of("schema","round","instance","offer","phase","admission","serial","members"))||!Set.of("true","false").contains(m.get("admission")))throw new IOException("CONTROL73_JOURNAL");var offer=RemoteOffer69.decode(Base64.getDecoder().decode(m.get("offer")));if(!m.get("schema").equals("73")||!m.get("round").equals(round.toString())||!offer.signer().equals(FirstLaunchFiles.sha(keys.publicBytes)))throw new IOException("CONTROL73_JOURNAL");ControlRoom73 r=new ControlRoom73(root,offer,UUID.fromString(m.get("instance")),round,keys.key,keys.pub);r.phase=m.get("phase");r.admission=Boolean.parseBoolean(m.get("admission"));r.serial=Long.parseLong(m.get("serial"));if(!Set.of("PREPARING","COMMITTED","CANCELLED","CLOSED").contains(r.phase)||r.serial<0)throw new IOException("CONTROL73_JOURNAL");if(r.phase.equals("PREPARING")){if(offer.expires()<System.currentTimeMillis())r.phase="CANCELLED";else offer.validAt(System.currentTimeMillis());}
  if(!m.get("members").isEmpty())for(String row:m.get("members").split(";")){String[] v=row.split(",",-1);if(v.length!=10||r.accounts.size()>=64)throw new IOException("CONTROL73_JOURNAL");Member a=new Member(UUID.fromString(v[0]),UUID.fromString(v[1]),HexFormat.of().parseHex(v[2]),Boolean.parseBoolean(v[3]));a.decision=v[4];a.state=v[5];a.inventory=v[6];a.ack=UUID.fromString(v[7]);a.counted=Boolean.parseBoolean(v[8]);a.last=v[9];if(a.secret.length!=32||!Set.of("true","false").contains(v[3])||!Set.of("true","false").contains(v[8])||!Set.of("PENDING","ACCEPTED","DECLINED","EXPIRED").contains(a.decision)||!Set.of("WAITING","PREPARED","INSTALLED","JOINED","ABORTED").contains(a.state)||!a.inventory.equals("none")&&!a.inventory.matches("[a-f0-9]{64}")||!a.last.equals("none")&&!a.last.matches("[a-f0-9]{64}")||a.counted&&!a.original||r.accounts.values().stream().anyMatch(x->x.id.equals(a.id))||r.accounts.put(a.account,a)!=null)throw new IOException("CONTROL73_JOURNAL");}if((r.phase.equals("PREPARING")&&r.denominator()!=0)||r.phase.equals("COMMITTED")&&r.denominator()==0||r.admission&&(!r.phase.equals("COMMITTED")&&!r.phase.equals("CLOSED")||r.installed()<r.needed()))throw new IOException("CONTROL73_JOURNAL");return r;
 }
 public synchronized String phase(){return phase;}public synchronized boolean admission(){return admission;}public synchronized Collection<Member> members(){return List.copyOf(accounts.values());}
 public synchronized Member member(UUID account,boolean original){Member m=accounts.get(account);if(m==null){if(accounts.size()>=64)throw new IllegalStateException("CONTROL73_LIMIT");byte[] secret=new byte[32];new SecureRandom().nextBytes(secret);m=new Member(UUID.randomUUID(),account,secret,original);accounts.put(account,m);}return m;}
 public synchronized void decision(UUID account,String value){Member m=member(account,false);if(!Set.of("PENDING","ACCEPTED","DECLINED","EXPIRED").contains(value))throw new IllegalArgumentException();m.decision=value;}
 public synchronized Map<String,String> config(Member m,UUID ticket){return Map.ofEntries(Map.entry("schema","73"),Map.entry("authMode","ONLINE"),Map.entry("instance",instance.toString()),Map.entry("round",round.toString()),Map.entry("client",m.id.toString()),Map.entry("secret",HexFormat.of().formatHex(m.secret)),Map.entry("account",m.account.toString()),Map.entry("ticket",ticket.toString()),Map.entry("release",offer.release().toString()),Map.entry("archive",offer.archiveSha()),Map.entry("distribution",offer.distribution().toString()),Map.entry("game",offer.game()),Map.entry("endpoint",offer.endpoint()),Map.entry("signer",offer.signer()));}
 public synchronized void receipt(byte[] packet)throws Exception{
  for(Member m:accounts.values()){Map<String,String> d;try{d=LocalApply67.verify(m.secret,packet);}catch(IOException wrong){continue;}
   if(!d.keySet().equals(Set.of("schema","round","client","request","action","archive","inventory"))||!d.get("schema").equals("73")||!d.get("round").equals(round.toString())||!d.get("client").equals(m.id.toString())||!d.get("archive").equals(offer.archiveSha())||!d.get("inventory").matches("[a-f0-9]{64}"))throw new IOException("CONTROL73_RECEIPT");UUID request=UUID.fromString(d.get("request"));if(request.equals(new UUID(0,0)))throw new IOException("CONTROL73_RECEIPT");String fingerprint=FirstLaunchFiles.sha(packet);if(m.ack.equals(request)){if(!m.last.equals(fingerprint))throw new IOException("CONTROL73_CONFLICT");return;}
   if(!Set.of("PREPARING","COMMITTED").contains(phase)||!m.decision.equals("ACCEPTED"))throw new IOException("CONTROL73_DECISION");String action=d.get("action");String previousState=m.state,previousInventory=m.inventory,previousLast=m.last;UUID previousAck=m.ack;
   switch(action){case "PREPARED"->{if(phase.equals("COMMITTED")&&(!m.inventory.equals(d.get("inventory"))||m.state.equals("ABORTED")))throw new IOException("CONTROL73_ORDER");if(Set.of("INSTALLED","JOINED").contains(m.state)){if(!m.inventory.equals(d.get("inventory")))throw new IOException("CONTROL73_ORDER");}else{m.inventory=d.get("inventory");m.state="PREPARED";}}
    case "INSTALLED"->{if(!phase.equals("COMMITTED")||!Set.of("PREPARED","INSTALLED","JOINED").contains(m.state)||!m.inventory.equals(d.get("inventory")))throw new IOException("CONTROL73_ORDER");if(!m.state.equals("JOINED"))m.state="INSTALLED";}
    case "JOINED"->{if(!admission||!Set.of("INSTALLED","JOINED").contains(m.state)||!m.inventory.equals(d.get("inventory")))throw new IOException("CONTROL73_ORDER");m.state="JOINED";}
    case "ABORT"->{if(!phase.equals("PREPARING")||Set.of("INSTALLED","JOINED").contains(m.state))throw new IOException("CONTROL73_ORDER");m.state="ABORTED";}
    default->throw new IOException("CONTROL73_ACTION");}m.ack=request;m.last=fingerprint;try{persist();}catch(Exception failure){m.state=previousState;m.inventory=previousInventory;m.ack=previousAck;m.last=previousLast;throw failure;}return;
  }throw new IOException("CONTROL73_AUTH");
 }
 public synchronized void commit()throws Exception{
  if(!phase.equals("PREPARING"))throw new IOException("CONTROL73_PHASE");offer.validAt(System.currentTimeMillis());if(offer.expires()-System.currentTimeMillis()<300000)throw new IOException("CONTROL73_EXPIRING");int ready=0;
  for(Member m:accounts.values())if(m.original){if(m.decision.equals("PENDING")||m.decision.equals("ACCEPTED")&&!Set.of("PREPARED","ABORTED").contains(m.state))throw new IOException("CONTROL73_NOT_PREPARED");if(m.decision.equals("ACCEPTED")&&m.state.equals("PREPARED"))ready++;}
  if(ready==0)throw new IOException("CONTROL73_EMPTY");for(Member m:accounts.values())m.counted=m.original&&m.decision.equals("ACCEPTED")&&m.state.equals("PREPARED");phase="COMMITTED";try{persist();}catch(Exception failure){phase="PREPARING";for(Member m:accounts.values())m.counted=false;throw failure;}
 }
 public synchronized int denominator(){return (int)accounts.values().stream().filter(m->m.counted).count();}public synchronized int needed(){return Math.max(1,(denominator()+3)/4);}public synchronized int installed(){return (int)accounts.values().stream().filter(m->m.counted&&Set.of("INSTALLED","JOINED").contains(m.state)).count();}
 public synchronized void admit()throws Exception{if(!phase.equals("COMMITTED")||installed()<needed())throw new IOException("CONTROL73_THRESHOLD");boolean previous=admission;admission=true;try{persist();}catch(Exception failure){admission=previous;throw failure;}}
 public synchronized void cancel()throws Exception{if(!phase.equals("PREPARING"))throw new IOException("CONTROL73_IRREVERSIBLE");phase="CANCELLED";try{persist();}catch(Exception failure){phase="PREPARING";throw failure;}}
 public synchronized void closeRound()throws Exception{phase="CLOSED";persist();Files.deleteIfExists(root.resolve("active73"));}
 public synchronized void persist()throws Exception{
  String rows=accounts.values().stream().map(m->m.id+","+m.account+","+HexFormat.of().formatHex(m.secret)+","+m.original+","+m.decision+","+m.state+","+m.inventory+","+m.ack+","+m.counted+","+m.last).collect(java.util.stream.Collectors.joining(";"));
  FirstLaunchFiles.write(root.resolve(round+".journal"),ControlWire73.sign(key,Map.of("schema","73","instance",instance.toString(),"round",round.toString(),"offer",Base64.getEncoder().encodeToString(offer.encode()),"phase",phase,"admission",Boolean.toString(admission),"serial",Long.toString(++serial),"members",rows)),true);
 }
 public synchronized void publish(long now)throws Exception{
  Files.createDirectories(root.resolve("public"));Files.createDirectories(root.resolve("inbox"));FirstLaunchFiles.privateMode(root.resolve("inbox"));
  String clients=accounts.values().stream().map(m->m.id+","+m.state+","+m.ack).collect(java.util.stream.Collectors.joining(";"));
  var d=Map.ofEntries(Map.entry("schema","73"),Map.entry("instance",instance.toString()),Map.entry("round",round.toString()),Map.entry("release",offer.release().toString()),Map.entry("archive",offer.archiveSha()),Map.entry("distribution",offer.distribution().toString()),Map.entry("game",offer.game()),Map.entry("endpoint",offer.endpoint()),Map.entry("signer",offer.signer()),Map.entry("phase",phase),Map.entry("sequence",Long.toString(++serial)),Map.entry("expires",Long.toString(phase.equals("PREPARING")?Math.min(offer.expires(),now+10000):now+10000)),Map.entry("needed",Integer.toString(needed())),Map.entry("installed",Integer.toString(installed())),Map.entry("admission",Boolean.toString(admission)),Map.entry("clients",clients));
  persist();FirstLaunchFiles.write(root.resolve("auth73"),ControlWire73.encode(Map.of("schema","73","round",round.toString(),"clients",accounts.values().stream().map(m->m.id+":"+HexFormat.of().formatHex(m.secret)).collect(java.util.stream.Collectors.joining(";")))),true);FirstLaunchFiles.write(root.resolve("public").resolve(round+".state"),ControlWire73.sign(key,d),true);
 }
 public synchronized void drain()throws Exception{if(!Files.isDirectory(root.resolve("inbox")))return;try(var entries=Files.list(root.resolve("inbox"))){for(Path p:entries.limit(128).toList()){try{receipt(FirstLaunchFiles.read(p,16384));}catch(Exception rejected){}finally{Files.deleteIfExists(p);}}}}
}
